function playSound(completion:boolean,volume:number){try{const ctx=new AudioContext(),o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=completion?740:540;g.gain.setValueAtTime(.0001,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.13*Math.min(1,Math.max(0,volume)),ctx.currentTime+.04);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.42);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.43);o.onended=()=>void ctx.close()}catch(e){if(import.meta.env.DEV)console.error('Practice milestone sound failed:',e)}}
function Eyebrow({children}:any){return <div className="eyebrow">{children}</div>}

function XPPanel({xp}:any){return <section className="xp-panel" aria-label="Experience and level"><div className="xp-panel-main"><div className="xp-level-badge"><Sparkles size={17}/><span>LEVEL</span><b>{xp.level}</b></div><div className="xp-copy"><Eyebrow>VERIFIED PRACTICE EXPERIENCE</Eyebrow><h2>{xp.totalXp.toLocaleString()} <span>XP</span></h2><p><b>{xp.baseXp.toLocaleString()} base XP</b> from verified minutes ? <b>{xp.bonusXp.toLocaleString()} streak bonus XP</b></p></div></div><div className="xp-progress-block"><div className="xp-progress-label"><span>Level {xp.level} progress</span><b>{xp.xpIntoLevel} / {xp.xpForNextLevel} XP</b></div><div className="xp-progress-track"><span style={{width:`${xp.percent}%`}}/></div><small>{xp.remainingXp} XP to Level {xp.level+1}</small></div>{xp.next&&<div className="xp-next-streak">Next: <b>{xp.next.days}-day streak</b> ? {Math.max(0,xp.next.days-xp.streak)} qualifying {xp.next.days-xp.streak===1?'day':'days'} to go ? +{xp.next.bonusXp.toLocaleString()} XP</div>}<div className="xp-stats"><span><b>{xp.streak}</b> current streak</span><span><b>{xp.longestStreak}</b> longest streak</span><span><b>{xp.days}</b> qualifying days</span><span><b>{xp.milestones.filter((m:any)=>m.unlocked).length}/{xp.milestones.length}</b> achievements</span></div></section>}
function AchievementGallery({milestones}:any){return <section className="achievement-gallery"><div className="section-head"><div><Eyebrow>PROGRESS MILESTONES</Eyebrow><h2>Achievement gallery <span className="count-pill">{milestones.filter((m:any)=>m.unlocked).length}/{milestones.length}</span></h2></div></div><div className="achievement-gallery-grid">{milestones.map((m:any)=><article key={m.id} className={`progress-achievement ${m.unlocked?'unlocked':'locked'}`}><span className="progress-achievement-icon">{m.unlocked?<Check size={17}/>:<ShieldCheck size={17}/>}</span><div><b>{m.title}</b><small>{m.unlocked?'Unlocked':m.requirement}</small></div></article>)}</div></section>}
function Dashboard({data,now,active,totals,xp,onCreate,onAction,onOpen,onNavigate,onAchievement,onDelete}:any){const running=active&&data.draft?.segmentStartedAt!==null;const accum=totals.practiced+(running?Math.max(0,Math.floor((now-data.draft.segmentStartedAt)/1000)-data.draft.segmentSeconds):0);const overall=totals.target?Math.min(100,totals.practiced/totals.target*100):0;const counts={active:data.skills.filter((s:Skill)=>s.status==='In Progress').length,paused:totals.paused,complete:totals.completed};return <><div className="page-heading"><div><Eyebrow>MONDAY, PRACTICE IS PERSONAL</Eyebrow><h1>Make the hours <span>count.</span></h1><p>A clear view of your deliberate practice, one session at a time.</p></div><button className="button primary" onClick={onCreate}><Plus size={17}/> Add a skill</button></div><section className="summary-grid"><article className="summary-card featured-stat"><div className="stat-head"><span>TOTAL PRACTICE</span><Clock3 size={17}/></div><strong>{fmt(accum,true)}</strong><small>across {data.skills.length+(data.deletedSkills?.length??0)} tracked {data.skills.length+(data.deletedSkills?.length??0)===1?'skill':'skills'}</small><div className="stat-line"><span style={{width:`${overall}%`}}/></div></article><article className="summary-card"><div className="stat-head"><span>OVERALL PROGRESS</span><BarChart3 size={17}/></div><strong>{overall.toFixed(1)}<em>%</em></strong><small>weighted by your hour targets</small></article><article className="summary-card"><div className="stat-head"><span>ACTIVE PATHS</span><Activity size={17}/></div><strong>{counts.active.toString().padStart(2,'0')}</strong><small>{counts.paused} paused · {counts.complete} completed</small></article></section><XPPanel xp={xp}/>{running?<section className="active-panel"><div className="active-panel-left"><div className="live-tag"><span className="pulse"/> IN SESSION</div><Eyebrow>YOUR CURRENT FOCUS</Eyebrow><h2>{active.name}</h2><p>{active.level} <span>·</span> {fmt(active.targetSeconds/3600,true)} target</p><div className="active-progress"><span style={{width:`${progress(active)}%`}}/></div><small>{progress(active).toFixed(1)}% complete <span>·</span> {fmt(remaining(active),true)} left</small></div><div className="active-timer"><span>SESSION ELAPSED</span><strong>{fmt(currentElapsed(data.draft,now))}</strong><button className="button primary" onClick={()=>onAction('pause')}><Pause size={16} fill="currentColor"/> Pause session</button></div></section>:<section className="focus-empty"><div className="focus-icon"><Activity/></div><div><Eyebrow>YOUR PRACTICE, ON YOUR TERMS</Eyebrow><h2>Ready when you are.</h2><p>Choose a skill and begin a focused session. Your time is tracked locally on this device.</p></div><button className="button outline" onClick={()=>data.skills.length?onNavigate('Skills'):onCreate()}><Play size={16}/> {data.skills.length?'Choose a skill':'Create your first skill'}</button></section>}<div className="section-head"><div><Eyebrow>YOUR PRACTICE PATHS</Eyebrow><h2>Skills <span className="count-pill">{data.skills.length}</span></h2></div><button className="text-button" onClick={()=>onNavigate('Skills')}>View all skills <ChevronRight size={15}/></button></div>{data.skills.length?<div className="skill-grid">{data.skills.slice(0,3).map((s:Skill)=><SkillCard key={s.id} skill={s} onOpen={onOpen} onAction={onAction} active={active} onDelete={onDelete}/>)}</div>:<Empty icon={<Activity/>} title="Your first skill starts here" text="Add a skill to set your practice horizon and start tracking your progress." action="Add a skill" onClick={onCreate}/>}<CompletedSkills achievements={data.achievements} onOpen={onAchievement}/><AchievementGallery milestones={xp.milestones}/><div className="dashboard-bottom"><div className="quote-card"><div className="quote-mark">“</div><div><p>Mastery grows from attention paid<br/>to the work in front of you.</p><small>THE PRACTICE PRINCIPLE</small></div><div className="quote-art"><span/><span/><span/><span/><span/><span/></div></div><div className="today-card"><div className="today-top"><span>TODAY'S PRACTICE</span><Flame size={17}/></div><strong>{fmt(todayTotal(data.sessions)+(running?Math.max(0,Math.floor((now-data.draft.segmentStartedAt)/1000)):0),true)}</strong><small>time protected today</small><button onClick={()=>onNavigate('Session History')}>Open session history <ChevronRight size={14}/></button></div></div></>}
function SkillCard({skill:s,onOpen,onAction,active,onDelete}:any){return <article className="skill-card"><button className="card-open" onClick={()=>onOpen(s)} aria-label={"Open "+s.name}><span className={"skill-status "+(s.status==='In Progress'?'live':s.status==='Completed'?'done':s.status==='Paused'?'paused':'')}><span/>{s.status.toUpperCase()}</span><span className="card-arrow"><ChevronRight size={17}/></span><h3>{s.name}</h3><p>{s.level}</p><div className="skill-card-time"><div><span>LOGGED</span><b>{fmt(s.practicedSeconds,true)}</b></div><div><span>REMAINING</span><b>{fmt(remaining(s),true)}</b></div><div><span>TARGET</span><b>{(s.targetSeconds/3600).toLocaleString()}h</b></div></div><div className="progress-row"><div className="progress-track"><span style={{width:progress(s)+'%'}}/></div><b>{progress(s).toFixed(1)}%</b></div></button><div className="card-footer"><button className="button card-button" disabled={s.status==='Completed'} onClick={()=>onAction(active?.id===s.id?'resume':'start',s.id)}><Play size={14} fill="currentColor"/>{active?.id===s.id?'Resume':s.practicedSeconds?'Resume':'Start'} practice</button><span>Target locked <ShieldCheck size={13}/></span><button type="button" className="delete-skill-button" title={"Delete "+s.name} aria-label={"Delete skill "+s.name} onClick={e=>{e.stopPropagation();onDelete(s)}}>D</button></div></article>}
function SkillsPage({skills,active,onCreate,onAction,onOpen,onDelete}:any){return <><div className="page-heading"><div><Eyebrow>EVERY HOUR, ACCOUNTED FOR</Eyebrow><h1>Your skills.</h1><p>Each practice path has a fixed horizon and its own progress.</p></div><button className="button primary" onClick={onCreate}><Plus size={17}/> Add a skill</button></div>{skills.length?<div className="skill-grid all-skills">{skills.map((s:Skill)=><SkillCard key={s.id} skill={s} onOpen={onOpen} onAction={onAction} active={active} onDelete={onDelete}/>)}</div>:<Empty icon={<Activity/>} title="No skills yet" text="Start with a craft you want to practice deliberately." action="Add a skill" onClick={onCreate}/>}</>}
function SkillDetail({skill:s,data,now,active,onAction,onBack,onRename}:any){const resumable=active?.id===s.id?data.draft:data.pausedDrafts.find((d:any)=>d.skillId===s.id)??null;const live=active?.id===s.id&&data.draft?.segmentStartedAt!==null;const elapsed=resumable?currentElapsed(resumable,now):0;const effective=Math.min(s.targetSeconds,s.practicedSeconds+(live?Math.max(0,Math.floor((now-data.draft.segmentStartedAt)/1000)-data.draft.segmentSeconds):0));const left=Math.max(0,s.targetSeconds-effective);const [edit,setEdit]=useState(false),[name,setName]=useState(s.name);const pct=progress({...s,practicedSeconds:effective});return <><button className="back-link" onClick={onBack}><ArrowLeft size={15}/> Back to skills</button><div className="detail-heading"><div><Eyebrow>SKILL PROFILE · TARGET LOCKED</Eyebrow>{edit?<div className="rename"><input value={name} onChange={e=>setName(e.target.value)}/><button className="button primary small" onClick={()=>{onRename(s,name);setEdit(false)}}>Save name</button><button className="text-button" onClick={()=>setEdit(false)}>Cancel</button></div>:<h1>{s.name}<button className="edit-name" title="Edit skill name" onClick={()=>{setName(s.name);setEdit(true)}}>EDIT NAME</button></h1>}<p>{s.level} <span>·</span> {(s.targetSeconds/3600).toLocaleString()} hours</p></div><span className={`detail-status ${s.status==='Completed'?'done':''}`}><i/> {s.status}</span></div><section className="timers-grid"><article className={`timer-panel session-panel ${live?'running':''}`}><div className="timer-title"><span><span className="red-dot"/> CURRENT SESSION</span><Clock3 size={18}/></div><strong className="clock-display">{fmt(elapsed)}</strong><p>Elapsed in this focused session</p><div className="timer-buttons">{live?<button className="button secondary" onClick={()=>onAction('pause')}><Pause size={16} fill="currentColor"/> Pause</button>:active?.id===s.id&&data.draft?<button className="button primary" onClick={()=>onAction('resume')}><Play size={16} fill="currentColor"/> Resume session</button>:<button className="button primary" disabled={s.status==='Completed'} onClick={()=>onAction('start',s.id)}><Play size={16} fill="currentColor"/> Start session</button>}{active?.id===s.id&&data.draft&&<button className="button end-button" onClick={()=>onAction('end')}>End session</button>}</div></article><article className="timer-panel countdown-panel"><div className="timer-title"><span><AlarmClock size={16}/> MASTERY COUNTDOWN</span><span className="target-lock"><ShieldCheck size={14}/> FIXED TARGET</span></div><strong className="clock-display">{fmt(left)}</strong><p>Remaining to your {s.level.toLowerCase()} horizon</p><div className="countdown-bar"><span style={{width:`${pct}%`}}/></div><div className="countdown-foot"><span>{pct.toFixed(2)}% complete</span><span>{(s.targetSeconds/3600).toLocaleString()} total hours</span></div></article></section><section className="detail-stats"><div><span>ACCUMULATED</span><b>{fmt(effective,true)}</b><small>across all sessions</small></div><div><span>TARGET</span><b>{(s.targetSeconds/3600).toLocaleString()} hrs</b><small>{s.level}</small></div><div><span>SESSIONS</span><b>{data.sessions.filter((x:any)=>x.skillId===s.id).length+(active?.id===s.id&&live?1:0)}</b><small>saved segments</small></div><div><span>TODAY</span><b>{fmt(todayTotal(data.sessions,s.id)+(live?Math.max(0,Math.floor((now-data.draft.segmentStartedAt)/1000)):0),true)}</b><small>practice time</small></div></section><section className="detail-lower"><div className="panel history-preview"><div className="panel-heading"><div><Eyebrow>RECENT ACTIVITY</Eyebrow><h2>Session log</h2></div><History size={18}/></div>{data.sessions.filter((x:any)=>x.skillId===s.id).slice(0,5).map((x:any)=><div className="mini-session" key={x.id}><span className="session-date">{new Date(x.startedAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</span><span>{new Date(x.startedAt).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}</span><b>{fmt(x.durationSeconds,true)}</b><span className="session-state">{x.status}</span></div>)}{!data.sessions.some((x:any)=>x.skillId===s.id)&&<p className="muted">No saved sessions yet. Your first one begins here.</p>}</div><div className="panel milestones"><div className="panel-heading"><div><Eyebrow>PROGRESS MARKERS</Eyebrow><h2>Milestones</h2></div><Flame size={18}/></div><div className="milestone-list">{[25,50,75,90,100].map(m=><div className={`milestone-item ${pct>=m?'reached':''}`} key={m}><span>{pct>=m?<Check size={14}/>:<span className="milestone-empty"/>}</span><b>{m}%</b><small>{m===100?'Target reached':`${Math.round(s.targetSeconds*m/100/3600).toLocaleString()} practice hours`}</small></div>)}</div></div></section></>}
function Empty({icon,title,text,action,onClick}:any){return <section className="empty-state"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{text}</p><button className="button primary" onClick={onClick}><Plus size={16}/>{action}</button></section>}
function HistoryPage({data,range,setRange,filterSkill,setFilterSkill}:any){const now=Date.now(),floor=new Date();floor.setHours(0,0,0,0);const since=range==='Today'?floor.getTime():range==='Last 7 days'?now-7*86400000:range==='Last 30 days'?now-30*86400000:0;const rows=data.sessions.filter((s:any)=>s.startedAt>=since&&(filterSkill==='all'||s.skillId===filterSkill)).sort((a:any,b:any)=>b.startedAt-a.startedAt);const dayTotal=(days:number)=>data.sessions.filter((s:any)=>s.startedAt>=now-days*86400000).reduce((n:number,s:any)=>n+s.durationSeconds,0);const bars=Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(6-i));const val=data.sessions.filter((s:any)=>new Date(s.startedAt).toDateString()===d.toDateString()).reduce((n:number,s:any)=>n+s.durationSeconds,0);return{label:d.toLocaleDateString(undefined,{weekday:'short'}).slice(0,2),value:val}});const max=Math.max(3600,...bars.map(x=>x.value));return <><div className="page-heading"><div><Eyebrow>SHOW UP, THEN SHOW UP AGAIN</Eyebrow><h1>Session history.</h1><p>A record of the time you chose to protect.</p></div></div><div className="history-streak-strip"><div><Eyebrow>STREAK</Eyebrow><b>{currentQualifyingStreak(data.sessions,now)} current ? {longestQualifyingStreak(data.sessions)} longest</b><small>{nextStreakMilestone(currentQualifyingStreak(data.sessions,now))?`${nextStreakMilestone(currentQualifyingStreak(data.sessions,now))!.days-currentQualifyingStreak(data.sessions,now)} qualifying days to next bonus`:'All streak milestones reached'}</small></div><div className="practice-heatmap" aria-label="Last 30 days practice heatmap">{Array.from({length:30},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(29-i));const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,seconds=verifiedPracticeByLocalDay(data.sessions).get(key)??0;return <span key={key} title={`${key}: ${Math.floor(seconds/60)} verified minutes`} className={seconds>=900?'qualifying':seconds>0?'some-practice':''}/>})}</div></div><div className="history-summary"><div className="history-total"><Eyebrow>LAST 7 DAYS</Eyebrow><b>{fmt(dayTotal(7),true)}</b><span>practice logged</span></div><div className="history-total"><Eyebrow>LAST 30 DAYS</Eyebrow><b>{fmt(dayTotal(30),true)}</b><span>practice logged</span></div><div className="trend-card"><Eyebrow>YOUR WEEKLY RHYTHM</Eyebrow><div className="bar-chart">{bars.map((b,i)=><div className="bar-col" key={i}><span style={{height:`${Math.max(5,b.value/max*100)}%`}}/><small>{b.label}</small></div>)}</div></div></div><section className="panel history-table-panel"><div className="history-toolbar"><div><Eyebrow>PRACTICE RECORD</Eyebrow><h2>Recent sessions <span className="count-pill">{rows.length}</span></h2></div><div className="filters"><select value={filterSkill} onChange={e=>setFilterSkill(e.target.value)}><option value="all">All skills</option>{[...data.skills,...(data.deletedSkills??[])].map((s:Skill)=><option key={s.id} value={s.id}>{s.name}{data.deletedSkills?.some((d:Skill)=>d.id===s.id)?' (deleted)':''}</option>)}</select><select value={range} onChange={e=>setRange(e.target.value)}>{['Today','Last 7 days','Last 30 days','All time'].map(r=><option key={r}>{r}</option>)}</select></div></div><div className="history-table-wrap"><table><thead><tr><th>DATE</th><th>SKILL</th><th>START</th><th>END</th><th>DURATION</th><th>STATUS</th></tr></thead><tbody>{rows.map((s:any)=><tr key={s.id}><td>{new Date(s.startedAt).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</td><td className="table-skill">{s.skillName}</td><td>{new Date(s.startedAt).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}</td><td>{new Date(s.endedAt).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}</td><td>{fmt(s.durationSeconds,true)}</td><td><span className={`table-status ${s.status==='Completed'?'done':''}`}>{s.status}</span></td></tr>)}</tbody></table>{!rows.length&&<div className="table-empty"><History/><b>No sessions in this view</b><span>Completed practice segments will appear here.</span></div>}</div></section></>}
function SettingsPage({data,onSound,onSoundVolume,onSoundTest,soundTestError,onCelebrations,onUploadSound,onRemoveSound,fileInput,fileInputKey,onExport,onImport,onClear,milestoneSoundBlobs,milestoneSoundErrors,onMilestoneEnabled,onMilestoneDefaultAudio,onMilestoneUpload,onMilestoneTest,onMilestoneRemove,onMilestonePreview,milestonePreviewChoice,onMilestonePreviewChoice,milestoneAudioGuidance,onMilestoneAudioGuidance}:any){
 const prefs=data.preferences,tierInputs=useRef<Partial<Record<MilestoneTier,HTMLInputElement|null>>>({}),activeUploadButton=useRef<HTMLButtonElement|null>(null);
 const tiers:[MilestoneTier,string,string][]=[[25,'Bronze','The Awakening — restrained copper embers and a soft bronze halo.'],[50,'Silver','The Ascension — sharp chrome light and crystalline bursts.'],[100,'Legendary Gold','Berserk Transcendence — a staged golden power surge and sustained aura.']];
 const selectedTier:MilestoneTier=milestonePreviewChoice,selectedKey=tierKey(selectedTier),selectedTierName=tierLabel(selectedTier),selectedInfo=data.milestoneSoundInfo[selectedTier],selectedBlob=milestoneSoundBlobs[selectedTier],selectedEnabled=data.milestoneCelebrations[selectedKey],selectedFallback=data.milestoneDefaultAudio[selectedKey];
 const needsUpload=(tier:MilestoneTier)=>!milestoneSoundBlobs[tier]&&!data.milestoneDefaultAudio[tierKey(tier)];
 const guideUpload=()=>requestAnimationFrame(()=>activeUploadButton.current?.focus());
 const chooseTier=(tier:MilestoneTier)=>{onMilestonePreviewChoice(tier);onMilestoneAudioGuidance(needsUpload(tier)?`${tierLabel(tier)} needs its own audio file, or enable its default audio fallback.`:'');if(needsUpload(tier))guideUpload()};
 const previewTier=()=>{if(needsUpload(selectedTier)){onMilestoneAudioGuidance(`${selectedTierName} needs its own audio file, or enable its default audio fallback.`);guideUpload();return}onMilestonePreview(selectedTier)};
 return <><div className="page-heading"><div><Eyebrow>YOUR DATA, YOUR DEVICE</Eyebrow><h1>Settings.</h1><p>Manage sound, celebrations, backups, and local practice data.</p></div></div><div className="settings-layout"><section className="panel settings-panel"><div className="panel-heading"><div><Eyebrow>PREFERENCES</Eyebrow><h2>Practice environment</h2></div><Settings size={18}/></div><div className="setting-row"><div><b>Milestone sounds</b><small>Play sounds for milestones and completed skills.</small></div><button role="switch" aria-label="Milestone sounds" aria-checked={prefs.sounds} className={'toggle '+(prefs.sounds?'on':'')} onClick={()=>onSound(!prefs.sounds)}><span/></button></div><div className="volume-control"><label htmlFor="sound-volume"><span>Sound volume</span><output>{Math.round(prefs.soundVolume*100)}%</output></label><input id="sound-volume" type="range" min="0" max="100" step="1" value={Math.round(prefs.soundVolume*100)} onChange={e=>onSoundVolume(Number(e.target.value)/100)}/></div>
 <div className="custom-sound-section milestone-selected-audio"><div className="custom-sound-heading"><div><b>{selectedTierName} Audio — {selectedTier}%</b><small>{selectedBlob&&selectedInfo?selectedInfo.name:selectedInfo?'Saved file missing — upload it again':selectedFallback?'No custom sound uploaded; default fallback is enabled':`No custom sound uploaded for ${selectedTierName}.`}</small></div><button role="switch" aria-label={`Enable ${selectedTierName} ${selectedTier}% celebration`} aria-checked={selectedEnabled} className={'toggle '+(selectedEnabled?'on':'')} onClick={()=>onMilestoneEnabled(selectedTier,!selectedEnabled)}><span/></button></div>{[25,50,100].map(tier=><input key={tier} ref={node=>{tierInputs.current[tier as MilestoneTier]=node}} type="file" accept=".mp3,.wav,.ogg,.m4a,audio/mpeg,audio/wav,audio/ogg,audio/mp4" hidden onChange={e=>{const file=e.currentTarget.files?.[0];e.currentTarget.value='';void onMilestoneUpload(tier as MilestoneTier,file)}}/>)}<div className="custom-sound-actions"><button ref={activeUploadButton} className="button secondary" onClick={()=>tierInputs.current[selectedTier]?.click()}><Upload size={16}/>{selectedInfo?'Replace Sound':'Upload Sound'}</button><button className="button outline" onClick={()=>void onMilestoneTest(selectedTier)}><AlarmClock size={16}/> Test Sound</button><button className="button text-button remove-sound" disabled={!selectedInfo} onClick={()=>void onMilestoneRemove(selectedTier)}>Remove Sound</button></div><label className="milestone-fallback-setting"><input type="checkbox" checked={selectedFallback} onChange={e=>{onMilestoneDefaultAudio(selectedTier,e.target.checked);if(e.target.checked)onMilestoneAudioGuidance('')}}/> Use default audio if this tier has no custom file</label>{milestoneSoundErrors[selectedTier]&&<p className="sound-test-error" role="status">{milestoneSoundErrors[selectedTier]}</p>}</div>
 <div className="milestone-preview-control"><div><b>Test Celebration</b><small>Choose a tier to preview its visual effect and matching audio.</small></div><div className="milestone-preview-actions"><label className="sr-only" htmlFor="milestone-preview-tier">Choose milestone celebration tier</label><select id="milestone-preview-tier" value={selectedTier} onChange={e=>chooseTier(Number(e.target.value) as MilestoneTier)}><option value={25}>Bronze — 25%</option><option value={50}>Silver — 50%</option><option value={100}>Legendary Gold — 100%</option></select><button className="button outline" onClick={previewTier}><Sparkles size={16}/> Preview Celebration</button></div>{milestoneAudioGuidance&&<p className="milestone-audio-guidance" role="status">{milestoneAudioGuidance}</p>}</div>
 <details className="milestone-settings"><summary>Milestone Celebrations</summary><p className="settings-copy">Audio controls above follow the selected tier. The tier list below shows each independent saved file and setting.</p>{tiers.map(([tier,name,description])=>{const enabled=data.milestoneCelebrations[tierKey(tier)],info=data.milestoneSoundInfo[tier],blob=milestoneSoundBlobs[tier],fallback=data.milestoneDefaultAudio[tierKey(tier)];return <article key={tier} className={'milestone-audio-card milestone-card-'+tier}><div className="milestone-audio-head"><div><b>{name} <span>— {tier}%</span></b><small>{description}</small></div></div><p className="milestone-sound-name">{blob&&info?info.name:info?'Saved file missing — upload it again':fallback?'No custom sound; default fallback enabled':'No custom sound uploaded'}</p><small className="milestone-disabled-hint">Celebration {enabled?'enabled':'disabled'} · Default fallback {fallback?'enabled':'disabled'}</small></article>})}</details>
 <div className="custom-sound-section default-fallback-audio"><div className="custom-sound-heading"><div><b>Default Fallback Sound</b><small>{data.customSound?data.customSound.name:'Built-in generated tone'}</small></div>{data.customSound&&<button className="text-button remove-sound" onClick={onRemoveSound}>Remove / Restore Default</button>}</div><input key={fileInputKey} ref={fileInput} type="file" accept=".mp3,.wav,.ogg,.m4a,audio/mpeg,audio/wav,audio/ogg,audio/mp4" hidden onChange={(e:any)=>void onUploadSound(e.target.files?.[0])}/><div className="custom-sound-actions"><button className="button secondary" onClick={()=>fileInput.current?.click()}><Upload size={16}/> Upload Default</button><button className="button outline" onClick={()=>void onSoundTest()}><AlarmClock size={16}/> Test Default Sound</button></div>{soundTestError&&<p className="sound-test-error" role="status">{soundTestError}</p>}</div>
 <div className="setting-row celebration-setting"><div><b>Completion celebrations</b><small>Show the full-screen celebration when a skill reaches its target.</small></div><button role="switch" aria-label="Automatic completion celebrations" aria-checked={prefs.celebrations} className={'toggle '+(prefs.celebrations?'on':'')} onClick={()=>onCelebrations(!prefs.celebrations)}><span/></button></div><div className="backup-reminder"><ShieldCheck/><span><b>Keep a backup somewhere safe.</b><small>Export periodically. Your practice history lives in this browser only.</small></span></div></section><section className="panel settings-panel"><div className="panel-heading"><div><Eyebrow>PORTABLE BY DESIGN</Eyebrow><h2>Backup &amp; restore</h2></div><Download size={18}/></div><p className="settings-copy">Export your skills, practice history, milestones, custom celebration sounds, deleted skill history, and preferences as a JSON file.</p><div className="settings-buttons"><button className="button primary" onClick={onExport}><ArrowDownToLine size={16}/> Export data</button><button className="button secondary" onClick={onImport}><Upload size={16}/> Import backup</button></div></section><section className="panel settings-panel danger-zone"><div className="panel-heading"><div><Eyebrow>IRREVERSIBLE</Eyebrow><h2>Clear local data</h2></div><Trash2 size={18}/></div><p className="settings-copy">Remove all skills, saved sessions, milestones, and preferences from this device.</p><button className="button danger-outline" onClick={onClear}><Trash2 size={15}/> Clear all data</button></section><section className="panel settings-panel about-panel"><div className="panel-heading"><div><Eyebrow>THE PRACTICE PRINCIPLE</Eyebrow><h2>Progress, honestly measured.</h2></div><Activity size={18}/></div><p className="settings-copy">Hour targets are a way to protect time for deliberate practice. Reaching a target does not guarantee mastery; learning is personal, and the work continues beyond any number.</p><span className="offline-label"><span className="green-dot"/> OFFLINE READY AFTER FIRST LOAD</span></section></div></>}function DeleteConfirm({skill,onCancel,onDelete}:any){return <div className="modal-backdrop delete-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onCancel()}}><section className="modal delete-confirm" role="dialog" aria-modal="true" aria-labelledby="delete-skill-title"><div className="modal-top"><div className="eyebrow">REMOVE ACTIVE SKILL</div><button className="icon-btn" onClick={onCancel} aria-label="Cancel deletion"><X/></button></div><h2 id="delete-skill-title">Delete {skill.name}?</h2><p className="modal-intro">This removes the skill from your active list. Its saved practice sessions, completion record, and achievement will remain in your history and backup.</p><div className="modal-actions"><button className="button secondary" onClick={onCancel}>Cancel</button><button className="button danger" onClick={onDelete}><Trash2 size={16}/> Delete skill</button></div></section></div>}
